function trainMenu(){E.sync();open(tr('<h2>ผลิตกองกำลัง</h2><p id="trainSummary"></p><p>แตะ +1 ตามจำนวนที่ต้องการ • เริ่มพร้อมกันทุกตัว<br>พื้นที่นับรวมหน่วยที่กำลังผลิตแล้ว</p><div class="grid">')+U.map(function(u,i){return'<div><button id="trainButton'+i+'" onclick="Game.train('+i+')"><span class="train-art">'+cardSprite(u.sprite)+'<span id="trainClock'+i+'" class="train-clock" hidden>◷</span></span><b>'+u.name+'</b><small>'+u.cost+tr(' พลังงาน')+(u.crystals?' / '+u.crystals+tr(' ผลึก'):'')+' • '+u.time+tr(' วินาที • พื้นที่ ')+u.space+'<br>'+({machine:tr('ปืนกล'),cannon:tr('ปืนใหญ่'),grenade:tr('ระเบิดมือ'),heal:tr('ลำแสงรักษา'),sniper:tr('กระสุนเจาะเกราะ'),missile:tr('ขีปนาวุธ'),shock:tr('หมัดไฟฟ้า'),bomb:tr('ระเบิดพื้นที่'),plasma:tr('ลูกพลาสมา')}[u.weapon])+'</small><small id="trainStatus'+i+tr('" class="train-status"></small><b>+1 หน่วย</b></button><button class="wide" onclick="Game.enhanceInfo(\'unit:')+i+tr('\',1)">ข้อมูล / ตีบวก +')+plusLevel(E.d.enhancements,'unit:'+i)+'</button></div>';}).join('')+tr('</div><p id="queue"></p><button class="wide gem" onclick="Game.speedQueue()">💎 เร่งผลิตทั้งหมด</button><button class="wide" onclick="Game.close()">กลับฐาน</button>'));updateTraining();}
function updateTraining(){if(!$('trainSummary')||modal.style.display==='none')return;$('trainSummary').textContent=tr('พื้นที่ ')+E.housing()+'/'+E.capacity()+tr(' • พลังงาน ')+Math.floor(E.d.power);U.forEach(function(u,i){var jobs=E.d.queue.filter(function(q){return q.kind===i;}),lock=E.unitLock(i),reason=lock||((E.d.logistics277&&u.air?E.used277(true)+u.space>E.airCapacity277():E.housing()+u.space>E.capacity())?tr('พื้นที่ไม่พอ'):E.d.power<u.cost?tr('พลังงานไม่พอ'):E.d.crystals<(u.crystals||0)?tr('ผลึกไม่พอ'):tr('พร้อมผลิต'));$('trainButton'+i).disabled=!!lock||(E.d.logistics277&&u.air?E.used277(true)+u.space>E.airCapacity277():E.housing()+u.space>E.capacity())||E.d.power<u.cost||E.d.crystals<(u.crystals||0);$('trainClock'+i).hidden=!jobs.length;$('trainStatus'+i).textContent=jobs.length?tr('กำลังผลิต ')+jobs.length+tr(' • ตัวถัดไป ')+duration((Math.min.apply(null,jobs.map(function(q){return q.until;}))-E.now())/1000):reason;});$('queue').textContent=queueText();}

