function result(){var r=E.raid.result;if(r.stars>0&&!r.heard362){r.heard362=true;if(soundOn)playClip250('winning362');}if(E.raid.practice){open(tr('<h2>ผลการบุกทดสอบ</h2><p>ทำลาย ')+r.percent+'% • '+r.stars+tr(' ดาว<br>คุณวางกำลังเองและดูการต่อสู้ในสนาม<br>สนามซ้อมไม่หักทหารหรือทรัพยากรเจ้าของฐาน</p><button class="wide green" onclick="Game.practiceAgain()">สุ่มฐานถัดไป</button><button class="wide" onclick="Game.home()">กลับฐาน</button>'));hud();return;}open('<h2>'+(r.stars?tr('ภารกิจสำเร็จ'):tr('ถอนกำลัง'))+'</h2><div class="stars">'+'★'.repeat(r.stars)+'☆'.repeat(3-r.stars)+tr('</div><p>ทำลาย ')+r.percent+tr('%<br>ได้ ')+r.gold+tr(' ทอง และ ')+r.power+tr(' พลังงาน</p>')+'<p>+'+(r.gems||0)+' NOVA'+(r.pending362?mt251(' • รอยืนยันเมื่อเชื่อมต่อ',' • Pending connection'):'')+tr('</p><p>กำลังพลที่รอดชีวิตกลับฐานแล้ว<br>ทหารที่ยังไม่ปล่อยยังอยู่ในค่าย</p><button class="wide green" onclick="Game.home()">กลับฐาน</button>'));hud();}
