root.Game={treasury:treasury,speedConfirm:speedConfirm,speed:function(id,price){toast(E.speed(id,price)||tr('ก่อสร้างเสร็จแล้ว'));close();hud();},tradeConfirm:function(kind){open(tr('<h2>แลกทรัพยากร</h2><p>ใช้ 10 เพชร แลก 5,000 ')+(kind==='gold'?tr('ทอง'):tr('พลังงาน'))+'</p><button class="wide green" onclick="Game.trade(\''+kind+tr('\')">ยืนยันแลก</button><button class="wide" onclick="Game.treasury()">กลับ</button>'));},trade:function(kind){toast(E.exchange(kind)||tr('แลกทรัพยากรแล้ว'));hud();treasury();},checkin:function(){var n=E.claim();toast(n?tr('รับ ')+n+tr(' เพชรแล้ว'):tr('รับรางวัลวันนี้แล้ว'));hud();treasury();},rewardAd:function(){if(root.NovaAds&&root.NovaAds.reward)root.NovaAds.reward();else root.novaRewardStatus('unconfigured');},home:home,close:close,build:buildMenu,training:trainMenu,missions:missions,place:function(k){placing=k;moving=null;selected=null;close();hud();},train:function(i){var msg=E.train(i);if(msg)toast(msg);updateTraining();hud();},collect:function(){var v=E.collect();toast(tr('เก็บ ')+v.gold+tr(' ทอง / ')+v.power+tr(' พลังงาน'));hud();},upgrade:function(){var wall=E.d.buildings.find(function(b){return b.id===selected&&b.type==='wall';});if(wall){Game.wallConfirm('one');return;}var msg=E.upgrade(selected);toast(msg||tr('เริ่มอัปเกรดแล้ว'));hud();},scout:function(n){E.sync();if(!E.d.army.some(function(n){return n>0;})&&!(E.d.mercenaries&&E.d.mercenaries.attack)&&!(E.d.titan342&&E.d.titan342.level&&E.titanRecovery347&&!E.titanRecovery347().resting)){toast(tr('ฝึกทหารก่อนออกบุก'));return;}if(!E.scout(n)){toast(mt251('ด่านนี้ยังไม่ปลดล็อก','This stage is locked'));return;}screen='raid';paused=false;selected=null;placing=null;moving=null;panX=panY=0;zoom=1;close();hud();},unit:function(i){deployKind=i;hud();},pause:pause,resume:function(){paused=false;close();last=performance.now();},retreat:function(){E.finish();paused=false;result();},zoom:function(v){zoom=Math.max(.35,Math.min(1.5,zoom+v));drawNeeded=true;},cancel:function(){placing=null;moving=null;selected=null;hud();},help:function(){open(tr('<h2>ผู้บัญชาการ ยินดีต้อนรับ!</h2><p>1. เหมืองและเครื่องสกัดส่งผลผลิตเข้าคลังอัตโนมัติจนเต็ม<br>2. สร้างฐาน อัปเกรดศูนย์บัญชาการเพื่อปลดล็อกโรงงาน<br>3. ฝึกกองทัพ แล้วออกบุกฐานต่างดาว<br>4. เลือกชนิดทหาร แล้วแตะพื้นที่ว่างเพื่อปล่อยกำลัง</p><p>ฐานหลักเล่นออฟไลน์ได้ • เปิดสงครามออนไลน์ผ่านเมนูภารกิจเพื่อบุกผู้เล่นที่เข้าร่วม<br>ทหารที่ส่งออกรบจะถูกใช้ไป ฝึกทดแทนได้</p><button class="wide green" onclick="Game.close()">เริ่มบัญชาการ</button><button class="wide" onclick="Game.privacy()">ความเป็นส่วนตัว / โฆษณา</button>'));},privacy:function(){open(tr('<h2>ความเป็นส่วนตัว</h2><p>Nova Striker • Cockro Network<br>เล่นออฟไลน์ได้โดยไม่สมัคร ข้อมูลฐานอยู่ในอุปกรณ์ การลบข้อมูลแอปทำให้เซฟในเครื่องหาย<br>เมื่อล็อกอินด้วย Google จะสำรองเซฟไป Supabase ได้ตามที่คุณเลือก<br>เมื่อเข้าร่วมสงครามออนไลน์ จะเก็บผังฐาน ระดับ และรายงานการรบ ผู้เล่นอื่นเห็นรหัสผู้บัญชาการและแนวป้องกัน<br>ถอนฐานและลบข้อมูลสงครามได้จากเมนูออนไลน์ ส่วนเซฟคลาวด์ลบได้จากเมนูบัญชี</p><p>Google Ads อาจใช้ IP รหัสโฆษณา และข้อมูลการใช้งานตามความยินยอมของคุณ</p><button class="wide" onclick="if(window.NovaAds)NovaAds.settings()">ตั้งค่าโฆษณา</button><p><a href="https://nova-striker-privacy.fit-rain-4305.chatgpt.site">นโยบายฉบับเต็ม</a><br>sunan.tongsan@gmail.com</p><button class="wide" onclick="Game.close()">กลับ</button>'));}};
var audio=null,soundOn=localStorage.getItem('novaSound')!=='off';
function sound(freq,length){if(!soundOn||!audio||audio.state!=='running')return;try{var o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;o.type='sine';g.gain.setValueAtTime(.025,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+length);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+length);}catch(e){}}
