Game.speedQueue=function(){E.sync();if(!E.d.queue.length){toast(tr('คิวฝึกว่าง'));return;}var cost=novaSpeedPrice365((Math.max.apply(null,E.d.queue.map(function(q){return q.until;}))-E.now())/1000);open(tr('<h2>เร่งฝึกทั้งหมด</h2><p>')+E.d.queue.length+tr(' หน่วย • ใช้ ')+cost+tr(' เพชร</p><button class="wide green" onclick="Game.finishQueue(')+cost+tr(')">ยืนยัน</button><button class="wide" onclick="Game.training()">กลับ</button>'));};
Game.finishQueue=function(cost){toast(E.speedTraining(cost)||tr('กองทัพพร้อมแล้ว'));trainMenu();hud();};
Game.activities=function(){open(tr('<h2>ศูนย์ภารกิจ</h2><button class="wide green" onclick="Game.findWar()">🌐 ทำสงคราม</button><button class="wide green" onclick="Game.defenseInfo()">👾 ป้องกันฐาน • ระลอก ')+E.d.defenseLevel+tr('</button><button class="wide" onclick="Game.garrison()">กองกำลังป้องกันฐาน</button><button class="wide" onclick="Game.tasks()">🎯 ภารกิจรายวัน</button><button class="wide" onclick="Game.missions()">⚔ แผนที่ต่างดาว • บอสทุก 5 ด่าน</button><button class="wide" onclick="Game.cloud()">☁ บัญชีและเซฟออนไลน์</button><button class="wide" onclick="Game.toggleSound()">เสียง: ')+(soundOn?tr('เปิด'):tr('ปิด'))+tr('</button><button class="wide" onclick="Game.close()">กลับฐาน</button>'));};
Game.toggleSound=function(){soundOn=!soundOn;try{localStorage.setItem('novaSound',soundOn?'on':'off');}catch(e){}Game.activities();};
Game.tasks=function(){var t=E.d.tasks,today=t.day===E.day();open(tr('<h2>ภารกิจประจำวัน</h2><p>แต่ละภารกิจให้ 5 เพชร • รีเซ็ตเที่ยงคืนไทย</p>')+[['build',2,tr('สร้างหรืออัปเกรด')],['train',5,tr('ฝึกทหารสำเร็จ')],['win',2,tr('ชนะด่านบุก')],['defend',1,tr('ป้องกันฐานสำเร็จ')]].map(function(a){var count=today?t[a[0]]||0:0,claimed=today&&t.claimed.indexOf(a[0])>=0;return'<button class="wide" '+(claimed||count<a[1]?'disabled':'')+' onclick="Game.claimTask(\''+a[0]+'\')">'+a[2]+' '+Math.min(count,a[1])+'/'+a[1]+' • '+(claimed?tr('รับแล้ว'):tr('รับ 5 💎'))+'</button>';}).join('')+tr('<button class="wide" onclick="Game.close()">กลับ</button>'));};
Game.claimTask=function(k){toast(E.claimTask(k)?tr('รับ 5 เพชรแล้ว'):tr('ยังรับไม่ได้'));Game.tasks();hud();};
Game.defenseInfo=function(){open(tr('<h2>ต่างดาวบุกฐาน</h2><p>ระลอก ')+E.d.defenseLevel+tr(' • เตรียมป้อมและกำแพงก่อนเริ่ม<br>กำจัดศัตรูทั้งหมดใน 2 นาทีและรักษาฐานหลัก<br>ชนะรับทรัพยากรและ 3 เพชร ปลดล็อกระลอกถัดไป<br>เป็นโหมดฝึกป้องกัน ความเสียหายจะซ่อมคืนฟรีเมื่อจบ ไม่เสียอาคารถาวร</p><button class="wide green" onclick="Game.startDefense()">เริ่มป้องกันฐาน</button><button class="wide" onclick="Game.close()">กลับ</button>'));};
Game.startDefense=function(){var msg=E.startDefense();if(msg){toast(msg);return;}screen='defense';selected=null;placing=moving=null;paused=false;zoom=.85;panX=0;panY=-110;close();hud();};
function defenseResult(){var r=E.defense.result;open('<h2>'+(r.win?tr('ป้องกันฐานสำเร็จ!'):tr('ฐานถูกยึด'))+tr('</h2><p>ได้ ')+r.gold+tr(' ทอง / ')+r.power+tr(' พลังงาน / ')+r.gems+tr(' เพชร<br>อาคารทุกหลังจะซ่อมคืนให้พร้อมลองใหม่</p><button class="wide green" onclick="Game.home()">กลับฐาน</button>'));hud();}
Game.endDefense=function(){E.finishDefense(false);paused=false;defenseResult();};
var cloudRevision=0,cloudLoaded=false,cloudCandidate=null,loginDestination="cloud";
function safeCampaign(d){return d&&d.version===1&&Number.isFinite(d.gold)&&d.gold>=0&&Number.isFinite(d.power)&&d.power>=0&&Number.isFinite(d.gems)&&d.gems>=0&&Number.isInteger(d.next)&&Array.isArray(d.buildings)&&d.buildings.length>0&&d.buildings.length<=200&&d.buildings.filter(function(b){return b.type==='hq';}).length===1&&d.buildings.every(function(b){return B[b.type]&&Number.isInteger(b.id)&&Number.isInteger(b.x)&&b.x>=1&&b.x<=GRID_PAID391&&Number.isInteger(b.y)&&b.y>=1&&b.y<=GRID_PAID391&&Number.isInteger(b.lv)&&b.lv>=1&&b.lv<=MAX_BUILDING_LEVEL&&(!b.until||Number.isFinite(b.until));})&&new Set(d.buildings.map(function(b){return b.id;})).size===d.buildings.length&&new Set(d.buildings.map(function(b){return b.x+','+b.y;})).size===d.buildings.length&&d.next>Math.max.apply(null,d.buildings.map(function(b){return b.id;}))&&Array.isArray(d.army)&&d.army.length>=9&&d.army.length<=U.length&&d.army.every(function(n){return Number.isInteger(n)&&n>=0&&n<=10000;})&&Array.isArray(d.queue)&&d.queue.length<=300&&d.queue.every(function(q){return Number.isInteger(q.kind)&&U[q.kind]&&Number.isFinite(q.until);})&&Number.isFinite(d.last)&&Number.isInteger(d.stage)&&d.stage>=1&&d.stage<=100&&d.stars&&typeof d.stars==='object'&&(!d.tasks||Number.isInteger(d.tasks.day)&&Array.isArray(d.tasks.claimed))&&(!d.checkin||Number.isInteger(d.checkin.day)&&Number.isInteger(d.checkin.streak))&&(!d.rewardIds||Array.isArray(d.rewardIds));}
// Account controls must remain accessible even when cloud-save loading fails.
var accountId282='';
function accountDetails282(){try{var c=root.NovaCloud;return c&&c.accountInfo?JSON.parse(c.accountInfo()):{};}catch(e){return {};}}
Game.cloud=function(){
 loginDestination="cloud";
 var c=root.NovaCloud,ready=!!(c&&c.available&&c.available()),info=accountDetails282(),telegram=!!(c&&c.provider==='telegram');
 var signed=!!(info.id||accountId282||(c&&c.hasAccount&&c.hasAccount()));
 var label=info.email||info.id||accountId282|| (signed?mt251('เข้าสู่ระบบแล้ว','Signed in'):mt251('ยังไม่ได้เข้าสู่ระบบ','Not signed in'));
 open('<h2>'+mt251('จัดการบัญชี','Manage account')+'</h2><p style="overflow-wrap:anywhere">'+escapeHTML(label)+'</p>'+
 (info.provider?'<p>'+mt251('เข้าเกมด้วย ','Signed in with ')+escapeHTML(({google:'Google',facebook:'Facebook',email:'Email',playgames:'Play Games'})[info.provider]||info.provider)+'</p>':'')+
 (Array.isArray(info.providers)&&info.providers.includes('facebook')&&info.providers.includes('google')?'<p>'+mt251('Google และ Facebook เชื่อมกับฐานนี้','Google and Facebook are linked to this base')+'</p>':'')+
 (signed?'<button class="wide" onclick="Game.cloudLoad()">'+tr('ตรวจเซฟออนไลน์')+'</button>':'')+
 (!telegram?'<button class="wide" '+(!ready?'disabled':'')+' onclick="Game.cloudLogin()">'+(signed?mt251('เลือกบัญชี Google','Choose Google account'):tr('เข้าสู่ระบบด้วย Google'))+'</button><button class="wide" onclick="Game.emailForm()">'+tr('อีเมล / รหัสผ่าน')+'</button><button class="wide" onclick="Game.emailForm(\'recover\')">'+tr('ลืมรหัสผ่าน')+'</button>':'<button class="wide" onclick="Game.cloudLogin()">'+mt251('เข้าสู่ระบบด้วย Telegram','Sign in with Telegram')+'</button>')+
 (signed?'<button class="wide" onclick="Game.accountLogout282()">'+tr('ออกจากระบบ')+'</button>':'')+
 '<p>'+mt251('การเปลี่ยนบัญชีไม่ย้ายฐานหรือ NOVA ให้อัตโนมัติ ตรวจบัญชีให้ถูกต้องก่อนสำรองหรือกู้คืน','Switching accounts does not transfer your base or NOVA automatically. Check the account before backing up or restoring.')+'</p><button class="wide" onclick="Game.close()">'+tr('กลับ')+'</button>');
};
Game.accountLogout282=function(){open('<h2>'+tr('ออกจากระบบ')+'?</h2><p>'+mt251('ฐานในเครื่องยังอยู่ คุณสามารถเข้าสู่บัญชีเดิมอีกครั้งได้','Your local base stays on this device. You can sign in again.')+'</p><button class="wide" onclick="Game.accountLogoutNow282()">'+mt251('ยืนยันออกจากระบบ','Confirm sign out')+'</button><button class="wide" onclick="Game.cloud()">'+tr('ยกเลิก')+'</button>');};
Game.accountLogoutNow282=function(){if(root.NovaCloud&&root.NovaCloud.logout){close();root.NovaCloud.logout();}};

Game.emailForm=function(mode){mode=mode||'login';var signup=mode==='signup',reset=mode==='recover',update=mode==='update';open('<h2>'+(signup?tr('สมัครด้วยอีเมล'):reset?tr('ลืมรหัสผ่าน'):update?tr('ตั้งรหัสผ่านใหม่'):tr('เข้าสู่ระบบด้วยอีเมล'))+'</h2><form onsubmit="Game.emailSubmit(event,\''+mode+'\')">'+(!update?tr('<label>อีเมล<input id="authEmail" type="email" autocomplete="email" maxlength="254" required style="display:block;width:100%;box-sizing:border-box;padding:12px;font-size:16px"></label>'):'')+(!reset?tr('<label>รหัสผ่าน<input id="authPassword" type="password" autocomplete="')+(signup||update?'new-password':'current-password')+'" minlength="'+(signup||update?8:1)+'" maxlength="128" required style="display:block;width:100%;box-sizing:border-box;padding:12px;font-size:16px"></label>':'')+(signup?tr('<p>รหัสผ่านอย่างน้อย 8 ตัวอักษร ต้องยืนยันอีเมลก่อนเข้าเล่น</p>'):'')+'<button class="wide green" type="submit">'+(signup?tr('สมัครสมาชิก'):reset?tr('ส่งลิงก์ตั้งรหัสผ่าน'):update?tr('บันทึกรหัสผ่าน'):tr('เข้าสู่ระบบ'))+'</button></form>'+(!update?'<button class="wide" onclick="Game.emailForm(\''+(signup?'login':'signup')+'\')">'+(signup?tr('มีบัญชีแล้ว'):tr('สมัครสมาชิกใหม่'))+tr('</button><button class="wide" onclick="Game.emailForm(\'recover\')">ลืมรหัสผ่าน</button>'):'')+tr('<button class="wide" onclick="Game.cloud()">กลับ</button>'));};
Game.emailSubmit=function(event,mode){event.preventDefault();var email=$('authEmail')?$('authEmail').value.trim():'',password=$('authPassword')?$('authPassword').value:'';if(!root.NovaCloud||!root.NovaCloud.emailAuth){toast(tr('ใช้งานผ่านแอป Android รุ่นล่าสุด'));return;}if($('authPassword'))$('authPassword').value='';root.NovaCloud.emailAuth(mode,email,password);toast(tr('กำลังดำเนินการ'));};
Game.cloudLogin=function(){if(root.NovaCloud){cloudLoaded=false;root.NovaCloud.login();}};
Game.cloudLoad=function(){if(root.NovaCloud){cloudLoaded=false;toast(tr('กำลังตรวจเซฟออนไลน์'));root.NovaCloud.load();}};
Game.cloudUpload=function(){if(!cloudLoaded)return;open(tr('<h2>สำรองฐานเครื่องนี้?</h2><p>บันทึกฐานปัจจุบันแทนเซฟออนไลน์ของบัญชีที่ล็อกอิน<br>ยอดเพชรนี้เป็นของโหมดออฟไลน์ ไม่ใช่ยอดซื้อเงินจริง</p><button class="wide green" onclick="Game.cloudUploadNow()">ยืนยันสำรอง</button><button class="wide" onclick="Game.cloud()">กลับ</button>'));};
Game.cloudUploadNow=function(){if(!cloudLoaded)return;E.sync();cloudLoaded=false;root.NovaCloud.save(JSON.stringify(E.d),cloudRevision);toast(tr('กำลังสำรองฐาน'));};
Game.cloudRestore=function(){if(!cloudCandidate||!safeCampaign(cloudCandidate))return;open(tr('<h2>กู้คืนฐานจากคลาวด์?</h2><p>ฐานในเครื่องจะเปลี่ยนเป็นเซฟที่เลือก<br>จะเก็บสำเนาฐานเดิมไว้ในเครื่องก่อนแทนที่</p><button class="wide green" onclick="Game.cloudRestoreNow()">ยืนยันกู้คืน</button><button class="wide" onclick="Game.cloud()">กลับ</button>'));};
Game.cloudRestoreNow=function(){if(!cloudCandidate||!safeCampaign(cloudCandidate))return;try{localStorage.setItem('novaRTSBeforeRestore',JSON.stringify(E.d));localStorage.setItem('novaRTS1',JSON.stringify(cloudCandidate));E=new Engine(localStorage);cloudCandidate=null;home();toast(tr('กู้คืนฐานแล้ว'));}catch(e){toast(tr('บันทึกในเครื่องไม่สำเร็จ ยังไม่เปลี่ยนฐาน'));}};
Game.cloudDelete=function(){open(tr('<h2>ลบเซฟ Nova ออนไลน์?</h2><p>ลบเฉพาะข้อมูล Nova ในบัญชีนี้ถาวร เซฟในเครื่องและข้อมูลเกมอื่นไม่ถูกลบ</p><button class="wide" onclick="Game.cloudDeleteNow()">ยืนยันลบเซฟออนไลน์</button><button class="wide" onclick="Game.cloud()">ยกเลิก</button>'));};
Game.cloudDeleteNow=function(){root.NovaCloud.deleteSave();};
root.novaCloudEvent=function(event,data){if(event==='signed_in'||event==='signed_out'){accountId282=event==='signed_in'?(data.id||''):'';testWallet=null;testTarget=null;clearTimeout(warTimer);warBusy=false;warActive=null;}if(event.indexOf('war')===0){warEvent(event,data);return;}if(event==='password_recovery'){Game.emailForm('update');return;}if(event==='status'){toast(data.message);return;}if(event==='signed_in'){warPending=null;warState=null;cloudLoaded=false;cloudCandidate=null;cloudRevision=0;if(loginDestination==='test'){loginDestination='cloud';Game.testShop();}else if(loginDestination==='war'){loginDestination='cloud';Game.war();}else Game.cloudLoad();return;}if(event==='loaded'){accountId282=data.id||accountId282;cloudRevision=data.save?data.save.revision:0;cloudLoaded=true;cloudCandidate=data.save?data.save.payload:null;var valid=cloudCandidate&&safeCampaign(cloudCandidate);open(tr('<h2>เซฟบัญชีของคุณ</h2><p>')+(data.save?tr('พบเซฟออนไลน์รุ่นที่ ')+cloudRevision:tr('ยังไม่มีเซฟออนไลน์'))+tr('</p><button class="wide green" onclick="Game.cloudUpload()">สำรองฐานเครื่องนี้</button>')+(valid?tr('<button class="wide" onclick="Game.cloudRestore()">กู้คืนฐานจากออนไลน์</button>'):'')+tr('<button class="wide" onclick="Game.cloudDelete()">ลบเซฟ Nova ออนไลน์</button><button class="wide" onclick="Game.accountLogout282()">ออกจากระบบ</button><button class="wide" onclick="Game.close()">กลับ</button>'));return;}if(event==='saved'){cloudRevision=data.revision;cloudLoaded=true;toast(tr('สำรองฐานออนไลน์แล้ว'));close();}if(event==='deleted'||event==='signed_out'){warPending=null;warState=null;cloudLoaded=false;cloudCandidate=null;cloudRevision=0;toast(event==='deleted'?tr('ลบเซฟออนไลน์แล้ว'):tr('ออกจากระบบแล้ว'));if(event==='signed_out')close();else Game.cloud();}};

var warState=null,warBusy=false,warPending=null,warTimer=null,warSerial=0,warActive=null,lastWarRequest=null;
function escapeHTML(v){return String(v).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c];});}
function warRequest(action,payload){
 if(warBusy){toast(tr('กำลังรอผลรายการเดิม กรุณารอสักครู่'));return;}
 if(!root.NovaCloud||!root.NovaCloud.warAvailable()){Game.war();return;}
 var id=String(++warSerial);warActive=id;warBusy=true;lastWarRequest={action:action,payload:payload||{}};
 var label=action==='test_claim'?tr('กำลังรับเพชรประจำวัน'):action.indexOf('test_')===0?tr('กำลังเชื่อมต่อศูนย์เพชร'):tr('กำลังติดต่อกองบัญชาการออนไลน์');
 if(resourcePolling||payload&&(payload.live||payload.enhance)){}else if(E.d.pendingCrystal||E.d.pendingWar||infrastructureAfterPublish){toast(tr('กำลังดำเนินการ…'));}else open('<h2>'+label+tr('</h2><p>กำลังโหลด…</p><button class="wide" onclick="Game.close()">กลับ</button>'));
 warTimer=setTimeout(function(){if(warActive!==id)return;warEvent('war_error',{request_id:id,message:tr('การเชื่อมต่อใช้เวลานาน กรุณาตรวจอินเทอร์เน็ตแล้วลองอีกครั้ง หากรับรางวัลสำเร็จแล้ว ระบบจะคืนยอดเดิม ไม่รับซ้ำ')});},45000);
 try{if(root.NovaCloud.warRequest)root.NovaCloud.warRequest(action,JSON.stringify(payload||{}),id);else root.NovaCloud.war(action,JSON.stringify(payload||{}));}catch(e){warEvent('war_error',{request_id:id,message:tr('เชื่อมต่อระบบออนไลน์ไม่ได้ กรุณาปิดแล้วเปิดเกมใหม่')});}
}
Game.retryWarRequest=function(){if(!lastWarRequest)return;var a=lastWarRequest.action,p=lastWarRequest.payload;if(a.indexOf('test_')===0||['status','history','targets'].includes(a)||p.request_id)warRequest(a,p);else warRequest('status');};
Game.war=function(){if(!root.NovaCloud||!root.NovaCloud.warAvailable()){open(tr('<h2>ทำสงคราม</h2><p>กำลังเตรียมเปิดให้บริการออนไลน์</p><p>บุกฐานผู้เล่นจริงแม้เจ้าของออฟไลน์ เลือกแผนแล้วรับรายงานการรบอัตโนมัติ<br>โล่หลังถูกบุก 30 นาที • พักจู่โจม 3 นาที<br>รุ่นนี้ยังเล่นด่านต่างดาวและป้องกันฐานออฟไลน์ได้ตามปกติ</p><button class="wide" onclick="Game.activities()">กลับ</button>'));return;}warRequest('status');};
function warMenu(){var d=warState;if(!d||!d.enrolled){open(tr('<h2>เข้าร่วมสงครามออนไลน์</h2><p>ส่งผังฐานปัจจุบันเข้าสนามรบ ผู้เล่นอื่นจะเห็นรหัสผู้บัญชาการและฐานของคุณ<br>สร้างโรงสังเคราะห์และคลังผลึกในฐานก่อน ส่งผังเพื่อเริ่มผลิตบนเซิร์ฟเวอร์<br>เมื่อเข้าร่วม ยอดผลึกในเครื่องจะเปลี่ยนเป็นยอดออนไลน์เดิม (บัญชีใหม่เริ่ม 0) ไม่บวกสองยอดรวมกัน<br>ใช้หน่วยจู่โจมออนไลน์ประจำการ เลือกแผนรบเพื่อส่งกำลัง</p><button class="wide green" onclick="Game.warPublish(true)">เข้าร่วมและส่งผังฐาน</button><button class="wide" onclick="Game.close()">กลับ</button>'));return;}var now=Date.parse(d.server_time),shield=Math.max(0,(Date.parse(d.shield_until)-now)/1000),cool=Math.max(0,(Date.parse(d.raid_after)-now)/1000);open(tr('<h2>ทำสงคราม</h2><p>')+escapeHTML(d.callsign)+tr(' • ระดับ ')+d.tier+'<br>🔮 '+d.crystals+' / '+d.capacity+tr(' • ผลิต ')+(d.rate||0)+tr(' / ชั่วโมง<br>ปล้นได้สูงสุด 60% • โล่ ')+duration(shield)+tr(' • หน่วยจู่โจมพัก ')+duration(cool)+tr('</p><button class="wide green" onclick="Game.warTargets()">ค้นหาคู่ต่อสู้</button><button class="wide" onclick="Game.warUpgrade()" ')+(d.tier>=15?'disabled':'')+tr('>ยกระดับกองกำลังและเกราะ • ')+(d.tier>=15?tr('สูงสุด'):d.tier*150+tr(' ผลึก'))+tr('</button><button class="wide" onclick="Game.onlineArsenal()">คลังแสง / กองกำลังป้องกันออนไลน์</button><button class="wide" onclick="Game.warPublish(false)">ส่งผังฐานปัจจุบันเพื่อเริ่มโรงผลิตผลึก</button><button class="wide" onclick="Game.retryOnline()">ตรวจรายการออนไลน์ค้าง</button><button class="wide" onclick="Game.warHistory()">รายงานบุก / ป้องกัน</button><button class="wide" onclick="Game.war()">รีเฟรชผลึกและเวลา</button><button class="wide" onclick="Game.warLeave()">ถอนฐานและลบข้อมูลสงคราม</button><button class="wide" onclick="Game.close()">กลับฐาน</button>'));}
Game.warPublish=function(enroll){warRequest(enroll?'enroll':'publish',{layout:E.d.buildings.filter(active).map(function(b){return{type:b.type,x:b.x,y:b.y,lv:b.lv};})});};
var targetCursor=-1;Game.practiceTargets=function(){warRequest('test_targets',{previous:testTarget&&testTarget.id});};Game.warTargets=function(after){targetCursor=-1;warRequest('targets',after?{after:after}:{});};Game.nextTarget=function(){if(warState&&warState.targets&&targetCursor+1<warState.targets.length){Game.warScout(++targetCursor);}else Game.warTargets(warState&&warState.targets&&warState.targets.length?warState.targets[warState.targets.length-1].id:null);};Game.warHistory=function(){warRequest('history');};
Game.warUpgrade=function(){if(!warState)return;open(tr('<h2>อัปเกรดกองกำลังออนไลน์</h2><p>ใช้ ')+warState.tier*150+tr(' ผลึก เพิ่มพลังจู่โจมและเกราะป้องกัน 1 ระดับ</p><button class="wide green" onclick="Game.warUpgradeNow()">ยืนยัน</button><button class="wide" onclick="Game.war()">กลับ</button>'));};Game.warUpgradeNow=function(){warRequest('upgrade');};
Game.warLeave=function(){open(tr('<h2>ถอนฐานออนไลน์?</h2><p>ลบระดับและรายงานสงครามของคุณถาวร ฐานออฟไลน์ยังอยู่</p><button class="wide" onclick="Game.warLeaveNow()">ยืนยันถอนฐานและลบข้อมูล</button><button class="wide" onclick="Game.war()">ยกเลิก</button>'));};Game.warLeaveNow=function(){warRequest('leave');};
function basePreview(layout){return tr('<svg viewBox="0 0 220 220" style="width:100%;max-height:240px;background:#365b43;border-radius:12px" aria-label="ผังฐานคู่ต่อสู้">')+layout.map(function(b){var color=b.type==='hq'?'#ffd36a':b.type==='wall'?'#a4adb2':['gun','tesla','cannonturret','missileturret'].includes(b.type)?'#f87865':'#84d8df';return '<rect x="'+(b.x*10-5)+'" y="'+(b.y*10-5)+'" width="9" height="9" rx="2" fill="'+color+'"/>';}).join('')+'</svg>';}
Game.warScout=function(index){targetCursor=index;var t=warState.targets[index];if(!t)return;warState.target=t;open('<h2>'+escapeHTML(t.callsign)+'</h2>'+basePreview(t.layout)+tr('<p>ระดับ ')+t.tier+tr(' • ปล้นได้สูงสุด<br>')+(t.loot_gold||0)+tr(' ทอง / ')+(t.loot_power||0)+tr(' พลังงาน</p>')+(t.can_attack===false?tr('<p>ฐานนี้มีโล่หรืออยู่ในช่วงพักบุกซ้ำ</p>'):tr('<label>แผนโจมตี <select id="warTactic"><option value="siege">ยานเกราะปิดล้อม</option><option value="infantry">ทหารกระจายตัว</option><option value="air">โจมตีทางอากาศ</option></select></label>'))+'<button class="wide green" '+(t.can_attack===false?'disabled':'')+mt251(" onclick=\"Game.attackSelected()\">โจมตี</button><button class=\"wide\" onclick=\"Game.nextTarget()\">ค้นหาต่อ • 100 ทอง</button><button class=\"wide\" onclick=\"Game.close()\">กลับฐาน</button>"," onclick=\"Game.attackSelected()\">Attack</button><button class=\"wide\" onclick=\"Game.nextTarget()\">Next base • 100 gold</button><button class=\"wide\" onclick=\"Game.close()\">Home</button>"));};
Game.attackSelected=function(){Game.warAttack($('warTactic').value||'siege');};
Game.warAttack=function(tactic){if(warBusy||!warState.target)return;if(!warPending){var bytes=new Uint8Array(16);root.crypto.getRandomValues(bytes);bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;var hex=Array.from(bytes).map(function(v){return('0'+v.toString(16)).slice(-2);}).join('');warPending={target:warState.target.id,tactic:tactic,request_id:hex.slice(0,8)+'-'+hex.slice(8,12)+'-'+hex.slice(12,16)+'-'+hex.slice(16,20)+'-'+hex.slice(20)};}warRequest('attack',warPending);};
function warEvent(event,message){if(message.request_id&&message.request_id!==warActive)return;clearTimeout(warTimer);warBusy=false;warActive=null;if(event==='war'&&message.action.indexOf('test_')===0){testEvent(message.action,message.data);return;}if(event==='war_login'){loginDestination=lastWarRequest&&lastWarRequest.action.indexOf('test_')===0?'test':'war';open(tr('<h2>เลือกวิธีเข้าเล่นออนไลน์</h2><p>เลือกสมัครด้วยอีเมล หรือเข้าสู่ระบบด้วย Google เพื่อเก็บความคืบหน้า</p><button class="wide green" onclick="Game.cloudLogin()">สมัคร / เข้าสู่ระบบ Google</button><button class="wide" onclick="Game.emailForm()">อีเมล / รหัสผ่าน</button><button class="wide" onclick="Game.close()">กลับ</button>'));return;}if(event==='war_error'){crystalPurchaseQuantity=0;open(tr('<h2>ยังไม่ได้รับผลจากเซิร์ฟเวอร์</h2><p>')+escapeHTML(message.message)+tr('</p><button class="wide green" onclick="Game.retryWarRequest()">ลองรายการเดิมอีกครั้ง</button><button class="wide" onclick="Game.testShop()">ตรวจยอดเพชรเดิม</button>')+(warPending?tr('<button class="wide green" onclick="Game.warRetry()">ตรวจรายการจู่โจมเดิมอีกครั้ง</button>'):'')+(E.d.pendingWar?tr('<button class="wide" onclick="Game.retryOnline()">ตรวจรายการออนไลน์เดิม</button><button class="wide" onclick="Game.cancelOnline()">ยกเลิกรายการที่ยังไม่สำเร็จ</button>'):'')+tr('<button class="wide" onclick="Game.war()">กลับกองบัญชาการ</button>'));return;}warState=message.data;var d=warState;if(message.action==='leave'){delete E.d.onlineCrystal;E.d.crystals=0;E.d.buildings.filter(function(b){return b.type==='crystalplant';}).forEach(function(b){b.collected=E.now();});E.save();}if(E.d.pendingWar&&message.action===E.d.pendingWar.action){delete E.d.pendingWar;E.save();}syncCrystal(d);if(message.action==='publish'&&infrastructureAfterPublish){var kind=infrastructureAfterPublish;infrastructureAfterPublish=null;warRequest('infrastructure',{kind:kind,economyVersion:2,request_id:nonce160()});return;}if(message.action==='infrastructure'){toast(d.receipt&&d.receipt.pending?tr('เริ่มอัปเกรดอาคารแล้ว'):tr('อัปเกรดอาคารสำเร็จ'));close();hud();return;}if(message.action==='cancel'){var receipt=d.receipt,p=E.d.pendingCrystal;if(receipt&&receipt.cancelled&&p&&receipt.id===p.request_id){E.d.gold+=p.gold||0;E.d.power+=p.power||0;delete E.d.pendingCrystal;}else if(p)finishCrystal(receipt);if(receipt&&E.d.pendingWar&&receipt.id===E.d.pendingWar.payload.request_id)delete E.d.pendingWar;E.save();Game.crystalCenter();return;}if(message.action==='fund'){finishCrystal(d.receipt);close();hud();return;}if(['forge','station'].includes(message.action)){onlineArsenal();return;}if(message.action==='research'){Game.crystalCenter();return;}if(message.action==='attack'&&d.report){warPending=null;open(tr('<h2>รายงานการจู่โจม</h2><p>ทำลาย ')+d.report.destruction+tr('%<br>ชิงทอง ')+(d.report.loot_gold||0)+tr('<br>ชิงพลังงาน ')+(d.report.loot_power||0)+tr('</p><button class="wide green" onclick="Game.war()">กลับกองบัญชาการ</button>'));return;}if(message.action==='targets'){if(d.targets.length){targetCursor=0;Game.warScout(0);return;}open('<h2>'+tr('ค้นหาผู้เล่น')+'</h2>'+(d.targets.length?d.targets.map(function(t,i){return'<button class="wide" onclick="Game.warScout('+i+')">'+escapeHTML(t.callsign)+' • Lv.'+t.tier+'</button>';}).join(''):tr('<p>ยังไม่พบฐานผู้เล่นอื่น • ฐานติดโล่ ')+(d.waiting_shield||0)+tr(' • รายการพักบุกซ้ำ ')+(d.waiting_rematch||0)+tr('<br>พักบุกคู่เดิม 30 นาที หรือเล่นด่านต่างดาวระหว่างรอ</p>'))+tr('<button class="wide" onclick="Game.war()">กลับ</button>'));return;}if(message.action==='history'){open(tr('<h2>รายงานสงคราม</h2>')+(d.history.length?d.history.map(function(r){return'<p>'+(r.attacking?tr('บุก'):tr('ถูกบุกโดย'))+' '+escapeHTML(r.opponent)+tr('<br>ทำลาย ')+r.destruction+'% • '+(r.attacking?'+':'−')+(r.loot_gold||0)+tr(' ทอง / ')+(r.loot_power||0)+tr(' พลังงาน<br>')+escapeHTML(new Date(r.created_at).toLocaleString('th-TH'))+'</p>';}).join(''):tr('<p>ยังไม่มีการรบ</p>'))+tr('<button class="wide" onclick="Game.war()">กลับ</button>'));return;}warMenu();}
Game.warRetry=function(){if(warPending)warRequest('attack',warPending);};

function nonce160(){var a=new Uint8Array(16);root.crypto.getRandomValues(a);a[6]=(a[6]&15)|64;a[8]=(a[8]&63)|128;var s=Array.from(a,function(n){return('0'+n.toString(16)).slice(-2);}).join('');return s.slice(0,8)+'-'+s.slice(8,12)+'-'+s.slice(12,16)+'-'+s.slice(16,20)+'-'+s.slice(20);}
Game.garrison=function(){open(tr('<h2>กองกำลังป้องกันฐาน</h2><p>ประจำการ ')+spaces(E.d.garrison)+' / '+E.garrisonCapacity()+tr(' พื้นที่<br>ใช้ทหารที่ฝึกแล้ว • ถอนกลับได้ • หลังจบป้องกันกลับมาครบ<br>ชุดนี้ใช้ป้องกันต่างดาวในเครื่อง</p>')+U.map(function(u,i){return'<div class="def-row"><b>'+u.name+tr('</b><small>พื้นที่ ')+u.space+tr(' • พร้อม ')+E.d.army[i]+tr(' • ประจำการ ')+E.d.garrison[i]+'</small><button onclick="Game.station('+i+tr(',1)">+ ประจำการ</button><button onclick="Game.station(')+i+tr(',-1)">− ถอน</button></div>');}).join('')+tr('<button class="wide" onclick="Game.war()">กองกำลังออนไลน์บนเซิร์ฟเวอร์</button><button class="wide" onclick="Game.close()">กลับ</button>'));};
Game.station=function(i,d){toast(E.station(i,d)||tr('จัดกำลังแล้ว'));Game.garrison();hud();};
var crystalPurchaseQuantity=0;
Game.crystalExchange=function(){open(tr('<h2>แลกผลึก</h2><p>10 เพชร = 1,000 ผลึก</p>')+[1,10,100,1000].map(function(q){return '<button class="wide green" onclick="Game.buyCrystals('+q+')">'+(q*10).toLocaleString()+' 💎 → '+(q*1000).toLocaleString()+tr(' ผลึก</button>');}).join('')+tr('<button class="wide" onclick="Game.close()">กลับ</button>'));};
Game.buyCrystals=function(q){if(!Number.isInteger(q)||q<1||q>1000)return;if(!E.d.onlineCrystal){toast(E.exchange('crystals',q)||tr('แลกผลึกแล้ว'));hud();Game.crystalExchange();return;}if(warBusy||E.d.pendingTest)return;if(E.d.gems<q*10){toast(tr('เพชรไม่พอ'));return;}if(E.d.crystals+q*1000>E.crystalCapacity()){toast(tr('พื้นที่คลังผลึกไม่พอ'));return;}crystalPurchaseQuantity=q;warRequest('test_claim');};
Game.crystalCenter=function(){E.sync();var online=!!E.d.onlineCrystal;open(tr('<h2>🔮 ศูนย์ผลึกโนวา</h2><button class="wide green" onclick="Game.crystalExchange()">💎 แลกเพชรเป็นผลึก</button><p>')+Math.floor(E.d.crystals)+' / '+E.crystalCapacity()+tr(' ผลึก • ')+E.crystalRate()+tr(' / ชั่วโมง<br>')+ (online?tr('ใช้ผลึกอัปเกรดจากปุ่มที่อาคารได้เลย'):tr('สร้างโรงสังเคราะห์ผลึกเมื่อฐานหลัก Lv.3<br>ผลผลิตเข้าคลังอัตโนมัติแม้ปิดเกม'))+tr('</p><p>ผลึกใช้ผลิตเครื่องบินทิ้งระเบิด พลพลาสมา รถถังพลาสมา หุ่นหนัก และอัปเกรดอาคาร Lv.6–15</p>')+[['weapon',tr('กระสุนเจาะเกราะ • พลังโจมตี +10% / ขั้น')],['armor',tr('เกราะพิเศษ • HP +10% / ขั้น')]].map(function(a){return'<button class="wide" onclick="Game.research(\''+a[0]+'\')">'+a[1]+'<br>Lv.'+E.d.research[a[0]]+'/5 • '+(50*(E.d.research[a[0]]+1))+tr(' ผลึก</button>');}).join('')+tr('<button class="wide" onclick="Game.training()">ผลิตอาวุธหนัก</button><button class="wide" onclick="Game.war()">รีเฟรช / จัดการผลึกออนไลน์</button><button class="wide" onclick="Game.build()">สร้างโรงผลิตและคลัง</button><button class="wide" onclick="Game.close()">กลับ</button>'));};
Game.research=function(kind){if(E.d.onlineCrystal&&upgradeJob225('research:'+kind)){toast(tr('กำลังวิจัย รอเวลาให้ครบ'));return;}if(E.d.onlineCrystal){warRequest('research',{kind:kind,economyVersion:2,request_id:nonce160()});return;}toast(E.buyResearch(kind)||tr('เริ่มวิจัยแล้ว'));Game.crystalCenter();};
function syncCrystal(d){if(!d||!d.enrolled)return;
 if(d.resources){
  E.sync();var ack=E.d.raidDeltas||{owner:d.owner,gold_delta:0,power_delta:0};
  if(ack.owner!==d.owner){toast(tr('กรุณาใช้บัญชีเดิมสำหรับฐานนี้'));return;}
  var previous=JSON.stringify(E.d);
  E.d.gold=Math.max(0,Math.min(E.resourceCapacity(),E.d.gold+d.resources.gold_delta-ack.gold_delta));
  E.d.power=Math.max(0,Math.min(E.resourceCapacity('power'),E.d.power+d.resources.power_delta-ack.power_delta));
  E.d.raidDeltas={owner:d.owner,gold_delta:d.resources.gold_delta,power_delta:d.resources.power_delta};
  E.d.resourceSeq=Math.max(E.d.resourceSeq||0,d.resources.seq||0);
  if(!E.save()){E.d=JSON.parse(previous);return;}
 }
E.d.crystals=0;E.d.onlineCrystal={owner:d.owner,capacity:d.capacity,rate:d.rate||0};if(d.research)E.d.research=d.research;if(d.infra)E.d.buildings.forEach(function(b){if(d.infra[b.type]&&active(b))b.lv=Math.max(b.lv,d.infra[b.type]);});E.d.buildings.filter(function(b){return b.type==='crystalplant';}).forEach(function(b){b.collected=E.now();});E.save();hud();}
var infrastructureAfterPublish=null;
Game.onlineBaseUpgrade=function(kind){if(!E.builderFree()){toast(tr('โดรนช่างกำลังทำงานครบทุกตัว'));return;}var b=E.d.buildings.find(function(b){return b.type===kind;});if(!b||b.until){toast(tr('รอการก่อสร้างให้เสร็จก่อน'));return;}if(b.lv>=E.hq()||b.lv>=MAX_BUILDING_LEVEL){toast(tr('อัปเกรดศูนย์บัญชาการก่อน'));return;}if(E.d.crystals<200*b.lv*b.lv){toast(tr('ต้องใช้ ')+200*b.lv*b.lv+tr(' ผลึก'));return;}if(kind==='garrison'&&warState&&b.lv>=warState.tier){open(tr('<h2>อัปเกรดอาคาร</h2><p>ต้องยกระดับกองกำลังออนไลน์ก่อน</p><button class="wide green" onclick="Game.warUpgrade()">ยกระดับกองกำลัง</button><button class="wide" onclick="Game.close()">กลับ</button>'));return;}if(warBusy)return;if(E.d.pendingWar){Game.retryOnline();return;}infrastructureAfterPublish=kind;Game.warPublish(false);};
Game.onlineForge=function(i){warRequest('forge',{kind:i,request_id:nonce160()});};
Game.onlineStation=function(i,delta){warRequest('station',{kind:i,delta:delta,request_id:nonce160()});};
