 if(!document.hidden&&screen==='home'&&E.d.onlineCrystal&&!liveRoom&&!warBusy&&!request362&&!searchQueued363&&!E.d.pendingCrystal&&!E.d.pendingWar&&!E.d.pendingTest){resourcePolling=true;warRequest('status');}
